import React, { useEffect, useState } from "react";
import Child from "./Child";

const Parent = () => {
  const [child, setChild] = useState([]);

  const childData = (val) => {
    setChild(val);
  };

  return (
    <div>
      {" "}
      <Child handleChildData={childData} />
      <h2>Child Data:</h2>
    </div>
  );
};

export default Parent;
